export function buildOrderMessage(input) { return [`Hello MODEA CLOTHING! I would like to place an order.`, ``, `ORDER SUMMARY`, ``, `Order Reference: ${input.reference}`, ``, ...input.items.flatMap((x, i) => [`${i + 1}. ${x.name}`, `   SKU: ${x.sku}`, `   Size: ${x.size}`, `   Color: ${x.color}`, `   Quantity: ${x.quantity}`, `   Unit Price: ${input.currency} ${x.unitPrice.toFixed(2)}`, `   Line Total: ${input.currency} ${x.lineTotal.toFixed(2)}`, ``]), `Subtotal: ${input.currency} ${input.subtotal.toFixed(2)}`, `Delivery Fee: ${input.deliveryFee ? `${input.currency} ${input.deliveryFee.toFixed(2)}` : 'To Be Confirmed'}`, `Estimated Total: ${input.currency} ${input.total.toFixed(2)}`, ``, `CUSTOMER DETAILS`, ``, `Name: ${input.customer.name}`, `Phone: ${input.customer.phone}`, `Delivery Address: ${input.customer.address}`, `City: ${input.customer.city}`, `Additional Notes: ${input.customer.notes || 'None'}`, ``, `Please confirm product availability, delivery charges, and the final order details.`, ``, `Thank you!`].join('\n'); }
export const whatsappUrl = (phone, message) => `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
